export type Optimized360Key = keyof typeof OPTIMIZED_360;

/** Devuelve los derivados optimizados de una foto /360 (o null si no existen). */
export function optimized360(src: string) {
  return (OPTIMIZED_360 as Record<string, (typeof OPTIMIZED_360)[Optimized360Key] | undefined>)[src] ?? null;
}
